def get_module(endpoint_id: str) -> ModuleType:
    module_path = PYDANTIC_MODULES[endpoint_id]
    return import_module(module_path)

def get_models(endpoint_id: str) -> dict[str, type[Any]]:
    module = get_module(endpoint_id)
    return {name: getattr(module, name) for name in PYDANTIC_MODEL_CLASSES[endpoint_id]}

def get_model(endpoint_id: str, class_name: str | None = None) -> type[Any]:
    models = get_models(endpoint_id)
    if class_name is None:
        return next(iter(models.values()))
    return models[class_name]
